import unittest

from roman import from_roman, to_roman

# (number, canonical Roman numeral) pairs covering every symbol and
# every subtractive pair.
KNOWN = [
    (1, "I"),
    (2, "II"),
    (3, "III"),
    (4, "IV"),
    (5, "V"),
    (6, "VI"),
    (9, "IX"),
