    (50, "L"),
    (58, "LVIII"),
    (88, "LXXXVIII"),
    (90, "XC"),
    (99, "XCIX"),
    (100, "C"),
    (400, "CD"),
    (444, "CDXLIV"),
    (500, "D"),
    (900, "CM"),
    (949, "CMXLIX"),
    (1000, "M"),
    (1444, "MCDXLIV"),
    (1666, "MDCLXVI"),
    (1900, "MCM"),
    (1987, "MCMLXXXVII"),
    (1994, "MCMXCIV"),
    (2024, "MMXXIV"),
    (2025, "MMXXV"),
    (3000, "MMM"),
    (3888, "MMMDCCCLXXXVIII"),
    (3999, "MMMCMXCIX"),
]


class ToRomanTests(unittest.TestCase):
    def test_single_symbols(self):
        cases = {1: "I", 5: "V", 10: "X", 50: "L", 100: "C", 500: "D", 1000: "M"}
        for n, expected in cases.items():
            with self.subTest(n=n):
                self.assertEqual(to_roman(n), expected)

    def test_known_values(self):
        for n, expected in KNOWN:
            with self.subTest(n=n):
                self.assertEqual(to_roman(n), expected)

    def test_out_of_range_raises(self):
        for n in (0, -1, 4000, 9999):
            with self.subTest(n=n):
                self.assertRaises(ValueError, to_roman, n)

    def test_non_integer_raises(self):
        for bad in ("10", 3.5, 10.0, None, True, [7], {7: 7}):
            with self.subTest(value=bad):
                self.assertRaises(TypeError, to_roman, bad)


class FromRomanTests(unittest.TestCase):
    def test_known_values(self):
        for n, roman in KNOWN:
            with self.subTest(roman=roman):
                self.assertEqual(from_roman(roman), n)

    def test_rejects_empty(self):
        for bad in ("", "   "):
            with self.subTest(value=bad):
                self.assertRaises(ValueError, from_roman, bad)

    def test_rejects_garbage(self):
        for bad in ("ABC", "I I", "X?", "XII!", "ROMAN"):
            with self.subTest(value=bad):
                self.assertRaises(ValueError, from_roman, bad)

    def test_rejects_non_canonical(self):
        for bad in ("IIII", "VV", "XXXX", "IL", "IC", "XD", "VX", "MMMM",
                    "IIV", "XIIII", "MCMC"):
            with self.subTest(value=bad):
                self.assertRaises(ValueError, from_roman, bad)

    def test_rejects_non_string(self):
        for bad in (None, 12, 3.14, ["XIV"]):
            with self.subTest(value=bad):
                self.assertRaises(TypeError, from_roman, bad)

    def test_case_and_whitespace_tolerant(self):
        self.assertEqual(from_roman("xiv"), 14)
        self.assertEqual(from_roman(" mmxxiv "), 2024)


class RoundTripTests(unittest.TestCase):
    def test_round_trip_every_number_1_to_3999(self):
        for n in range(1, 4000):
            with self.subTest(n=n):
                roman = to_roman(n)
                self.assertEqual(from_roman(roman), n)
                self.assertEqual(to_roman(from_roman(roman)), roman)

    def test_known_values_round_trip(self):
        for n, roman in KNOWN:
            with self.subTest(n=n):
                self.assertEqual(from_roman(to_roman(n)), n)
                self.assertEqual(to_roman(from_roman(roman)), roman)

    def test_no_symbol_repeats_more_than_three_times(self):
        for n in range(1, 4000):
            with self.subTest(n=n):
                roman = to_roman(n)
                for symbol in "IVXLCDM":
                    self.assertNotIn(symbol * 4, roman)

    def test_alphabet_and_length_bound(self):
        for n in range(1, 4000):
            with self.subTest(n=n):
                roman = to_roman(n)
                self.assertTrue(set(roman) <= set("IVXLCDM"))
                self.assertLessEqual(len(roman), 15)  # MMMCMXCIX


if __name__ == "__main__":
    unittest.main()
